DAN_STATIC_STR(dan_lit_1896, "    f.deg = p->deg;\n    return f;\n}\n\nstatic dl_Lr *dan_solve_rat(dan_mn p, int line) {\n    if (p->deg < 0) dan_error(DAN_MSG_ANY_X, line);\n    dl_Lr *r = dl_Lr_from(0, NULL);\n    if (p->deg == 0) return r;\n    dan_zpoly f = dan_zpoly_of(p, NULL, line);\n    dan_rroot *roots;\n    int64_t k = dan_rational_roots(&f, &roots, line);\n    qsort(roots, (size_t)k, sizeof(dan_rroot), dan_qcmp_rroot);\n    for (int64_t i = 0; i < k; i++) dl_Lr_push(r, roots[i].r);\n    dan_free(roots);\n    dan_free(f.z);\n    return r;\n}\n\nstatic dl_Lr *dan_solve_rat2(dan_mn a, dan_mn b, int line) { return dan_solve_rat(dan_poly_sub(a, b, line), line); }\n\n/* ---- real roots ---- */\n\ntypedef struct { double v; int exact; dan_rat r; } dan_root;\n\n/* Error-free transformations (Knuth, Dekker): a + b = s + e and a * b = p + e\n   exactly, in plain double arithmetic. They give the same result on every\n   processor, unlike long double (80 bits on x86, 64 bits on ARM) or fused\n   multiply-add, which the compiler is told not to use (-ffp-contract=off). */\nstatic void dan_two_sum(double a, double b, double *s, double *e) {\n    double x = a + b, z = x - a;\n    *e = (a - (x - z)) + (b - z);\n    *s = x;\n}\n\nstatic void dan_split(double a, double *h, double *l) {\n    double c = 134217729.0 * a;          /* 2^27 + 1 */\n    double big = c - a;\n    *h = c - big;\n    *l = a - *h;\n}\n\nstatic void dan_two_prod(double a, double b, double *p, double *e) {\n    double x = a * b, ah, al, bh, bl;\n    dan_split(a, &ah, &al);\n    dan_split(b, &bh, &bl);\n    *e = al * bl - (((x - ah * bh) - al * bh) - ah * bl);\n    *p = x;\n}\n\n/* Value of the polynomial c[0..n] at x by compensated Horner's scheme:\n   as accurate as if computed with twice the precision of double. */\nstatic double dan_horner_comp(const double *c, int n, double x) {\n    double s = c[n], err = 0;\n    for (int j = n - 1; j >= 0; j--) {\n        double p, pe, se;\n        dan_two_prod(s, x, &p, &pe);\n        dan_two_sum(p, c[j], &s, &se);\n        err = err * x + (pe + se);\n    }\n    return s + err;\n}\n\n/* Newton steps from a bracketed root with an accurate value of the\n   polynomial; then the neighbouring doubles are compared, so the result is\n   the double closest to the true root on every processor. */\nstatic double dan_polish(const double *c, int n, double x0) {\n    double x = x0;\n    for (int it = 0; it < 10; it++) {\n        double f = dan_horner_comp(c, n, x), d = 0;\n        for (int j = n; j >= 1; j--) d = d * x + c[j] * j;\n        if (f == 0 || d == 0) break;\n        double y = x - f / d;\n        if (y == x) break;\n        x = y;\n    }\n    if (x != x || fabs(x - x0) > 1e-6 * (fabs(x0) + 1)) return x0;   /* the Newton step went astray */\n    for (int it = 0; it < 4; it++) {\n        double fx = fabs(dan_horner_comp(c, n, x));\n        double lo = nextafter(x, -INFINITY), hi = nextafter(x, INFINITY);\n        double flo = fabs(dan_horner_comp(c, n, lo)), fhi = fabs(dan_horner_comp(c, n, hi));\n        if (flo < fx && flo <= fhi) x = lo;\n        else if (fhi < fx) x = hi;\n        else break;\n    }\n    return x;\n}\n\n/* Real roots of a polynomial with double coefficients c[0..n] that have\n   simple roots: the polynomial is monotone between roots of its derivative. */\nstatic int dan_real_roots_d(const double *c, int n, double *out) {\n    while (n > 0 && c[n] == 0) n--;\n    if (n <= 0) return 0;\n    if (n == 1) { out[0] = -c[0] / c[1]; return 1; }\n    double *d = dan_alloc(sizeof(double) * (size_t)n);\n    for (int i = 1; i <= n; i++) d[i - 1] = c[i] * i;\n    double *crit = dan_alloc(sizeof(double) * (size_t)(n + 1));\n    int nc = dan_real_roots_d(d, n - 1, crit);\n    double bound = 0;\n    for (int i = 0; i < n; i++) { double t = fabs(c[i] / c[n]); if (t > bound) bound = t; }\n    bound += 1;\n    double *pts = dan_alloc(sizeof(double) * (size_t)(nc + 2));\n    int np = 0;\n    pts[np++] = -bound;\n    for (int i = 0; i < nc; i++) if (crit[i] > -bound && crit[i] < bound) pts[np++] = crit[i];\n    pts[np++] = bound;\n    int k = 0;\n");
DAN_STATIC_STR(dan_lit_1897, "    for (int i = 0; i + 1 < np; i++) {\n        double lo = pts[i], hi = pts[i + 1];\n        double flo = 0, fhi = 0;\n        for (int j = n; j >= 0; j--) { flo = flo * lo + c[j]; fhi = fhi * hi + c[j]; }\n        if (flo == 0) { if (k == 0 || out[k - 1] != lo) out[k++] = lo; continue; }\n        if ((flo < 0) == (fhi < 0)) continue;\n        for (int it = 0; it < 200; it++) {\n            double mid = lo + (hi - lo) / 2, fm = 0;\n            if (mid <= lo || mid >= hi) break;\n            for (int j = n; j >= 0; j--) fm = fm * mid + c[j];\n            if (fm == 0) { lo = hi = mid; break; }\n            if ((fm < 0) == (flo < 0)) { lo = mid; flo = fm; } else hi = mid;\n        }\n        out[k++] = dan_polish(c, n, lo + (hi - lo) / 2);\n    }\n    dan_free(d); dan_free(crit); dan_free(pts);\n    return k;\n}\n\nstatic dan_mn dan_poly_gcd(dan_mn a, dan_mn b, int line) {\n    while (b->deg >= 0) { dan_mn r = dan_poly_mod(a, b, line); a = b; b = r; }\n    return a;\n}\n\nstatic int dan_qcmp_root(const void *a, const void *b) {\n    double x = ((const dan_root *)a)->v, y = ((const dan_root *)b)->v;\n    return (x > y) - (x < y);\n}\n\n/* All real roots: rational ones exactly, the others numerically. */\nstatic int64_t dan_poly_real_roots(dan_mn p, dan_root **out, int line) {\n    if (p->deg < 0) dan_error(DAN_MSG_ANY_X, line);\n    dan_root *roots = dan_alloc(sizeof(dan_root) * (size_t)(p->deg + 2));\n    int64_t k = 0;\n    if (p->deg <= 0) { *out = roots; return 0; }\n    dan_zpoly f = dan_zpoly_of(p, NULL, line);\n    dan_rroot *rr;\n    int64_t nr = dan_rational_roots(&f, &rr, line);\n    for (int64_t i = 0; i < nr; i++) {\n        roots[k].v = dan_rat_to_float(rr[i].r);\n        roots[k].exact = 1;\n        roots[k].r = rr[i].r;\n        k++;\n    }\n    if (f.deg >= 2) {                     /* the rest has no rational roots */\n        dan_poly *rest = dan_poly_alloc(f.deg);\n        for (int64_t i = 0; i <= f.deg; i++) {\n            if (f.z[i] > INT64_MAX || f.z[i] < -INT64_MAX) dan_error(DAN_MSG_POLY_BIG, line);\n            rest->c[i] = dan_rat_from_int((int64_t)f.z[i], line);\n        }\n        dan_mn g = dan_poly_gcd(rest, dan_poly_derivative(rest, line), line);\n        dan_mn sf = dan_poly_div(rest, g, line);          /* square-free part */\n        double *c = dan_alloc(sizeof(double) * (size_t)(sf->deg + 1));\n        for (int64_t i = 0; i <= sf->deg; i++) c[i] = dan_rat_to_float(sf->c[i]);\n        double *v = dan_alloc(sizeof(double) * (size_t)(sf->deg + 1));\n        int nv = dan_real_roots_d(c, (int)sf->deg, v);\n        for (int i = 0; i < nv; i++) { roots[k].v = v[i]; roots[k].exact = 0; k++; }\n        dan_free(c);\n        dan_free(v);\n    }\n    dan_free(rr);\n    dan_free(f.z);\n    qsort(roots, (size_t)k, sizeof(dan_root), dan_qcmp_root);\n    *out = roots;\n    return k;\n}\n\nstatic dl_Lf *dan_solve_real(dan_mn p, int line) {\n    dan_root *roots;\n    int64_t k = dan_poly_real_roots(p, &roots, line);\n    dl_Lf *r = dl_Lf_from(0, NULL);\n    for (int64_t i = 0; i < k; i++) dl_Lf_push(r, roots[i].v);\n    dan_free(roots);\n    return r;\n}\n\nstatic dl_Lf *dan_solve_real2(dan_mn a, dan_mn b, int line) { return dan_solve_real(dan_poly_sub(a, b, line), line); }\n\nstatic dl_Lf *dan_quadratic_roots(double a, double b, double c, int line) {\n    if (a == 0) dan_error(DAN_MSG_NOT_QUADRATIC, line);\n    dl_Lf *r = dl_Lf_from(0, NULL);\n    double d = b * b - 4 * a * c;\n    if (d < 0) return r;\n    if (d == 0) { dl_Lf_push(r, -b / (2 * a)); return r; }\n    double s = sqrt(d);\n    /* numerically stable form */\n    double q = -0.5 * (b + (b >= 0 \? s : -s));\n    double coef[3] = { c, b, a };\n    double x1 = dan_polish(coef, 2, q / a), x2 = dan_polish(coef, 2, c / q);\n    if (x1 > x2) { double t = x1; x1 = x2; x2 = t; }\n    dl_Lf_push(r, x1);\n    dl_Lf_push(r, x2);\n    return r;\n}\n\nstatic dan_rat dan_poly_discriminant(dan_mn p, int line) {\n    if (p->deg != 2) dan_error(DAN_MSG_DEG_TWO, line);\n    dan_rat a = p->c[2], b = p->c[1], c = p->c[0];\n");
DAN_STATIC_STR(dan_lit_1898, "    return dan_rat_sub(dan_rat_mul(b, b, line),\n                       dan_rat_mul(dan_rat_from_int(4, line), dan_rat_mul(a, c, line), line), line);\n}\n\n/* ---- factorization ---- */\n\nstatic void dan_buf_factor(dan_buf *b, dan_rat r, int64_t mult) {\n    /* root p/q -> (q\321\205 - p) */\n    dan_buf_add(b, \"(\");\n    if (r.d != 1) { char t[32]; snprintf(t, sizeof t, \"%\" PRId64, r.d); dan_buf_add(b, t); }\n    dan_buf_add(b, DAN_TXT_X);\n    char t[32];\n    snprintf(t, sizeof t, \" %c %\" PRId64, r.n > 0 \? '-' : '+', r.n > 0 \? r.n : -r.n);\n    dan_buf_add(b, t);\n    dan_buf_add(b, \")\");\n    if (mult > 1) {\n        char digits[24];\n        snprintf(digits, sizeof digits, \"%\" PRId64, mult);\n        for (char *p = digits; *p; p++) dan_buf_add(b, dan_sup[*p - '0']);\n    }\n}\n\nstatic void dan_buf_const_factor(dan_buf *b, dan_rat c, bool alone) {\n    if (alone) { dan_buf_rat(b, c); return; }\n    if (c.n == 1 && c.d == 1) return;\n    if (c.n == -1 && c.d == 1) { dan_buf_add(b, \"-\"); return; }\n    if (c.d != 1) { dan_buf_add(b, \"(\"); dan_buf_rat(b, c); dan_buf_add(b, \")\"); }\n    else dan_buf_rat(b, c);\n}\n\nstatic dan_str dan_factor_str(dan_mn p, int line) {\n    if (p->deg <= 0) return dan_poly_to_str(p);\n    dan_rat scale;\n    dan_zpoly f = dan_zpoly_of(p, &scale, line);\n    dan_rroot *roots;\n    int64_t k = dan_rational_roots(&f, &roots, line);\n    if (k == 0 && scale.n == 1 && scale.d == 1) { dan_free(roots); dan_free(f.z); return dan_poly_to_str(p); }   /* does not factor */\n    qsort(roots, (size_t)k, sizeof(dan_rroot), dan_qcmp_rroot);\n    dan_buf b = { NULL, 0, 0 };\n    dan_buf_add(&b, \"\");\n    dan_buf_const_factor(&b, scale, false);\n    for (int64_t i = 0; i < k; i++) {\n        if (roots[i].r.n == 0) dan_buf_power(&b, roots[i].mult);      /* \321\205^m */\n        else dan_buf_factor(&b, roots[i].r, roots[i].mult);\n    }\n    if (f.deg > 0) {\n        dan_poly *rest = dan_poly_alloc(f.deg);\n        for (int64_t i = 0; i <= f.deg; i++) rest->c[i] = dan_rat_from_int((int64_t)f.z[i], line);\n        dan_buf_add(&b, \"(\");\n        dan_buf_poly(&b, rest);\n        dan_buf_add(&b, \")\");\n    }\n    dan_free(roots);\n    dan_free(f.z);\n    return dan_buf_str(&b);\n}\n\n/* 2\321\205\302\262 + 6\321\205 -> 2\321\205(\321\205 + 3) */\nstatic dan_str dan_common_factor_str(dan_mn p, int line) {\n    if (p->deg < 0) return dan_poly_to_str(p);\n    int64_t low = 0, terms = 0;\n    while (p->c[low].n == 0) low++;\n    for (int64_t i = 0; i <= p->deg; i++) if (p->c[i].n != 0) terms++;\n    dan_rat scale;\n    dan_i128 *z = dan_poly_integer(p, &scale, line);\n    if (terms == 1 || (low == 0 && scale.n == 1 && scale.d == 1)) { dan_free(z); return dan_poly_to_str(p); }\n    dan_poly *rest = dan_poly_alloc(p->deg - low);\n    for (int64_t i = low; i <= p->deg; i++) rest->c[i - low] = dan_rat_from_int((int64_t)z[i], line);\n    dan_free(z);\n    dan_buf b = { NULL, 0, 0 };\n    dan_buf_add(&b, \"\");\n    dan_buf_const_factor(&b, scale, false);\n    if (low > 0) dan_buf_power(&b, low);\n    dan_buf_add(&b, \"(\");\n    dan_buf_poly(&b, rest);\n    dan_buf_add(&b, \")\");\n    return dan_buf_str(&b);\n}\n\n/* ---- inequalities: the interval method ---- */\n\nenum { DAN_LT, DAN_LE, DAN_GT, DAN_GE, DAN_EQ, DAN_NE };\n\nstatic int dan_parse_rel(dan_str s, int line) {\n    if (!strcmp(s, \"<\")) return DAN_LT;\n    if (!strcmp(s, \"<=\") || !strcmp(s, DAN_TXT_LE)) return DAN_LE;\n    if (!strcmp(s, \">\")) return DAN_GT;\n    if (!strcmp(s, \">=\") || !strcmp(s, DAN_TXT_GE)) return DAN_GE;\n    if (!strcmp(s, \"=\") || !strcmp(s, \"==\")) return DAN_EQ;\n    if (!strcmp(s, \"!=\") || !strcmp(s, DAN_TXT_NE)) return DAN_NE;\n    dan_conv_error(DAN_MSG_BAD_REL, s, line);\n    return 0;\n}\n\ntypedef struct { dan_mn p; int rel; dan_root *roots; int64_t nroots; } dan_atom;\n/* A condition is an OR of groups; a group is an AND of atoms. */\ntypedef struct { dan_atom *atoms; int64_t n; } dan_group;\n\nstatic bool dan_same_point(const dan_root *a, const dan_root *b) {\n    if (a->exact && b->exact) return dan_rat_cmp(a->r, b->r) == 0;\n    double m = fabs(a->v) > 1 \? fabs(a->v) : 1;\n");
DAN_STATIC_STR(dan_lit_1899, "    return fabs(a->v - b->v) <= 1e-9 * m;\n}\n\nstatic bool dan_rel_holds(int rel, int sign) {\n    switch (rel) {\n        case DAN_LT: return sign < 0;\n        case DAN_LE: return sign <= 0;\n        case DAN_GT: return sign > 0;\n        case DAN_GE: return sign >= 0;\n        case DAN_EQ: return sign == 0;\n        default: return sign != 0;\n    }\n}\n\n/* sign of the atom polynomial at a sample point (or at a breakpoint) */\nstatic int dan_atom_sign(const dan_atom *a, const dan_root *pt, double x) {\n    if (a->p->deg < 0) return 0;\n    if (pt) {\n        for (int64_t i = 0; i < a->nroots; i++) if (dan_same_point(&a->roots[i], pt)) return 0;\n        x = pt->v;\n    }\n    double v = dan_poly_eval_float(a->p, x);\n    return (v > 0) - (v < 0);\n}\n\nstatic bool dan_condition_holds(dan_group *g, int64_t ng, const dan_root *pt, double x) {\n    for (int64_t i = 0; i < ng; i++) {\n        bool all = true;\n        for (int64_t j = 0; j < g[i].n && all; j++)\n            all = dan_rel_holds(g[i].atoms[j].rel, dan_atom_sign(&g[i].atoms[j], pt, x));\n        if (all) return true;\n    }\n    return false;\n}\n\nstatic void dan_buf_point(dan_buf *b, const dan_root *r) {\n    if (r->exact) { dan_buf_rat(b, r->r); return; }\n    char t[64];\n    double v = dan_round_decimal(r->v, 4);\n    snprintf(t, sizeof t, \"%.4f\", v);\n    char *e = t + strlen(t) - 1;                 /* drop trailing zeros */\n    while (*e == '0') *e-- = 0;\n    if (*e == '.') *e = 0;\n    for (char *p = t; *p; p++) if (*p == '.') *p = ',';\n    if (!strcmp(t, \"-0\")) strcpy(t, \"0\");\n    dan_buf_add(b, t);\n}\n\nstatic dan_str dan_solve_condition(dan_group *g, int64_t ng, int line) {\n    /* breakpoints: roots of every polynomial */\n    int64_t cap = 16, nb = 0;\n    dan_root *bp = dan_alloc(sizeof(dan_root) * (size_t)cap);\n    for (int64_t i = 0; i < ng; i++)\n        for (int64_t j = 0; j < g[i].n; j++) {\n            dan_atom *a = &g[i].atoms[j];\n            a->nroots = 0;\n            a->roots = NULL;\n            if (a->p->deg <= 0) continue;\n            a->nroots = dan_poly_real_roots(a->p, &a->roots, line);\n            for (int64_t k = 0; k < a->nroots; k++) {\n                bool dup = false;\n                for (int64_t m = 0; m < nb && !dup; m++) dup = dan_same_point(&bp[m], &a->roots[k]);\n                if (dup) continue;\n                if (nb == cap) { cap *= 2; bp = dan_realloc(bp, sizeof(dan_root) * (size_t)cap); }\n                bp[nb++] = a->roots[k];\n            }\n        }\n    qsort(bp, (size_t)nb, sizeof(dan_root), dan_qcmp_root);\n    /* pieces: segment 0, point 0, segment 1, ..., point nb-1, segment nb */\n    int64_t np = 2 * nb + 1;\n    bool *in = dan_alloc(sizeof(bool) * (size_t)np);\n    for (int64_t s = 0; s <= nb; s++) {\n        double x;\n        if (nb == 0) x = 0;\n        else if (s == 0) x = bp[0].v - 1 - fabs(bp[0].v);\n        else if (s == nb) x = bp[nb - 1].v + 1 + fabs(bp[nb - 1].v);\n        else x = bp[s - 1].v + (bp[s].v - bp[s - 1].v) / 2;\n        in[2 * s] = dan_condition_holds(g, ng, NULL, x);\n        if (s < nb) in[2 * s + 1] = dan_condition_holds(g, ng, &bp[s], 0);\n    }\n    dan_buf b = { NULL, 0, 0 };\n    dan_buf_add(&b, \"\");\n    bool only_points = true, any = false;\n    for (int64_t i = 0; i < np; i++) if (in[i]) { any = true; if (i % 2 == 0) only_points = false; }\n    if (!any) { dan_buf_add(&b, DAN_TXT_NONE); goto done; }\n    if (only_points) {                           /* {a; b; c} */\n        dan_buf_add(&b, \"{\");\n        bool first = true;\n        for (int64_t i = 1; i < np; i += 2) if (in[i]) {\n            if (!first) dan_buf_add(&b, \"; \");\n            dan_buf_point(&b, &bp[i / 2]);\n            first = false;\n        }\n        dan_buf_add(&b, \"}\");\n        goto done;\n    }\n    bool first = true;\n    for (int64_t i = 0; i < np;) {\n        if (!in[i]) { i++; continue; }\n        int64_t j = i;\n        while (j + 1 < np && in[j + 1]) j++;\n        if (!first) dan_buf_add(&b, DAN_TXT_UNION);\n        first = false;\n");
DAN_STATIC_STR(dan_lit_1900, "        if (i == j && i % 2 == 1) {              /* isolated point */\n            dan_buf_add(&b, \"{\");\n            dan_buf_point(&b, &bp[i / 2]);\n            dan_buf_add(&b, \"}\");\n        } else {\n            /* piece i starts at: segment -> open at its left breakpoint; point -> closed */\n            if (i % 2 == 0) {\n                dan_buf_add(&b, \"(\");\n                if (i == 0) dan_buf_add(&b, DAN_TXT_MINF); else dan_buf_point(&b, &bp[i / 2 - 1]);\n            } else { dan_buf_add(&b, \"[\"); dan_buf_point(&b, &bp[i / 2]); }\n            dan_buf_add(&b, \"; \");\n            if (j % 2 == 0) {\n                if (j == np - 1) dan_buf_add(&b, DAN_TXT_PINF); else dan_buf_point(&b, &bp[j / 2]);\n                dan_buf_add(&b, \")\");\n            } else { dan_buf_point(&b, &bp[j / 2]); dan_buf_add(&b, \"]\"); }\n        }\n        i = j + 1;\n    }\ndone:\n    for (int64_t i = 0; i < ng; i++)\n        for (int64_t j = 0; j < g[i].n; j++) dan_free(g[i].atoms[j].roots);\n    dan_free(bp);\n    dan_free(in);\n    return dan_buf_str(&b);\n}\n\nstatic dan_str dan_ineq_str(dan_mn left, dan_str rel, dan_mn right, int line) {\n    dan_atom a = { dan_poly_sub(left, right, line), dan_parse_rel(rel, line), NULL, 0 };\n    dan_group g = { &a, 1 };\n    return dan_solve_condition(&g, 1, line);\n}\n\nstatic dan_str dan_ineq_system_str(const dl_Lp *lefts, const dl_Ls *rels, const dl_Lp *rights, int line) {\n    if (lefts->len != rels->len || lefts->len != rights->len) dan_error(DAN_MSG_INEQ_LISTS, line);\n    dan_atom *atoms = dan_alloc(sizeof(dan_atom) * (size_t)(lefts->len + 1));\n    for (int64_t i = 0; i < lefts->len; i++) {\n        atoms[i].p = dan_poly_sub(lefts->items[i], rights->items[i], line);\n        atoms[i].rel = dan_parse_rel(rels->items[i], line);\n    }\n    dan_group g = { atoms, lefts->len };\n    dan_str r = dan_solve_condition(&g, 1, line);\n    dan_free(atoms);\n    return r;\n}\n\n/* |p| rel c  <=>  (p >= 0 and p - c rel 0) or (p < 0 and -p - c rel 0) */\nstatic dan_str dan_abs_condition(dan_mn p, int rel, dan_mn c, int line) {\n    dan_atom g1[2] = { { p, DAN_GE, NULL, 0 }, { dan_poly_sub(p, c, line), rel, NULL, 0 } };\n    dan_atom g2[2] = { { p, DAN_LT, NULL, 0 }, { dan_poly_sub(dan_poly_neg(p, line), c, line), rel, NULL, 0 } };\n    dan_group g[2] = { { g1, 2 }, { g2, 2 } };\n    return dan_solve_condition(g, 2, line);\n}\n\nstatic dan_str dan_abs_eq_str(dan_mn p, dan_mn c, int line) { return dan_abs_condition(p, DAN_EQ, c, line); }\nstatic dan_str dan_abs_ineq_str(dan_mn p, dan_str rel, dan_mn c, int line) {\n    return dan_abs_condition(p, dan_parse_rel(rel, line), c, line);\n}\n\n/* ---- systems of linear equations: Gaussian elimination with exact fractions ---- */\n\nstatic dl_Lr *dan_solve_system(const dl_LLr *m, int line) {\n    int64_t n = m->len;\n    for (int64_t i = 0; i < n; i++) if (m->items[i]->len != n + 1) dan_error(DAN_MSG_SYS_SHAPE, line);\n    dan_rat *a = dan_alloc(sizeof(dan_rat) * (size_t)(n * (n + 1) + 1));\n    for (int64_t i = 0; i < n; i++)\n        for (int64_t j = 0; j <= n; j++) a[i * (n + 1) + j] = m->items[i]->items[j];\n#define A(i, j) a[(i) * (n + 1) + (j)]\n    int64_t row = 0;\n    int64_t *where = dan_alloc(sizeof(int64_t) * (size_t)(n + 1));\n    for (int64_t j = 0; j < n; j++) where[j] = -1;\n    for (int64_t col = 0; col < n && row < n; col++) {\n        int64_t piv = -1;\n        for (int64_t i = row; i < n; i++) if (A(i, col).n != 0) { piv = i; break; }\n        if (piv < 0) continue;\n        for (int64_t j = 0; j <= n; j++) { dan_rat t = A(row, j); A(row, j) = A(piv, j); A(piv, j) = t; }\n        dan_rat lead = A(row, col);\n        for (int64_t j = 0; j <= n; j++) A(row, j) = dan_rat_div(A(row, j), lead, line);\n        for (int64_t i = 0; i < n; i++) {\n            if (i == row || A(i, col).n == 0) continue;\n            dan_rat f = A(i, col);\n            for (int64_t j = 0; j <= n; j++)\n                A(i, j) = dan_rat_sub(A(i, j), dan_rat_mul(f, A(row, j), line), line);\n        }\n        where[col] = row;\n        row++;\n    }\n");
DAN_STATIC_STR(dan_lit_1901, "    for (int64_t i = row; i < n; i++) if (A(i, n).n != 0) dan_error(DAN_MSG_SYS_NONE, line);\n    if (row < n) dan_error(DAN_MSG_SYS_MANY, line);\n    dl_Lr *r = dl_Lr_from(0, NULL);\n    for (int64_t j = 0; j < n; j++) dl_Lr_push(r, A(where[j], n));\n#undef A\n    dan_free(a);\n    dan_free(where);\n    return r;\n}\n");
DAN_STATIC_STR(dan_lit_1902, "\n/* ==== higher and applied mathematics ==== */\n\n/* -- elementary functions -- */\n/* \320\242\320\260\320\261\320\273\320\270\321\207\320\275\321\213\320\265 \321\203\320\263\320\273\321\213 (\320\272\321\200\320\260\321\202\320\275\321\213\320\265 \320\277\320\270/12, \321\202\320\276 \320\265\321\201\321\202\321\214 15\302\260) \320\264\320\260\321\216\321\202 \321\202\320\276\321\207\320\275\321\213\320\265 \321\202\320\260\320\261\320\273\320\270\321\207\320\275\321\213\320\265 \320\267\320\275\320\260\321\207\320\265\320\275\320\270\321\217:\n   \321\201\320\270\320\275\321\203\321\201(\320\277\320\270 / 6) = 0.5, \320\260 \320\275\320\265 0.49999999999999994, \320\272\320\260\320\272 \320\262 \320\264\321\200\321\203\320\263\320\270\321\205 \321\217\320\267\321\213\320\272\320\260\321\205. */\nstatic bool dan_table_angle(double x, int64_t *k) {\n    double q = x / (3.141592653589793 / 12);\n    if (!(fabs(q) < 1e12)) return false;\n    double r = nearbyint(q);\n    if (fabs(q - r) > 1e-9) return false;\n    *k = (((int64_t)r % 24) + 24) % 24;\n    return true;\n}\nstatic double dan_sin_table(int64_t k, double x) {   /* sin(k\302\26715\302\260), k = 0..23 */\n    static const double h = 0.7071067811865476, t = 0.8660254037844386;\n    switch (k) {\n        case 0: case 12: return 0.0;\n        case 2: case 10: return 0.5;\n        case 3: case 9: return h;\n        case 4: case 8: return t;\n        case 6: return 1.0;\n        case 14: case 22: return -0.5;\n        case 15: case 21: return -h;\n        case 16: case 20: return -t;\n        case 18: return -1.0;\n    }\n    return sin(x);\n}\nstatic double dan_sin(double x, int line) {\n    (void)line;\n    int64_t k;\n    return dan_table_angle(x, &k) \? dan_sin_table(k, x) : sin(x);\n}\nstatic double dan_cos(double x, int line) {\n    (void)line;\n    int64_t k;\n    return dan_table_angle(x, &k) \? dan_sin_table((k + 6) % 24, x + 1.5707963267948966) : cos(x);\n}\nstatic double dan_tan(double x, int line) {\n    int64_t k;\n    if (dan_table_angle(x, &k)) {\n        double s = dan_sin_table(k, x), c = dan_sin_table((k + 6) % 24, x + 1.5707963267948966);\n        if (c == 0) dan_error(DAN_MSG_TAN, line);\n        switch (k % 12) {\n            case 0: return 0.0;\n            case 2: return 0.5773502691896257;     /* \342\210\2323/3, \320\261\320\273\320\270\320\266\320\260\320\271\321\210\320\265\320\265 \320\264\320\262\320\276\320\270\321\207\320\275\320\276\320\265 \321\207\320\270\321\201\320\273\320\276 */\n            case 3: return 1.0;\n            case 4: return 1.7320508075688772;     /* \342\210\2323 */\n            case 8: return -1.7320508075688772;\n            case 9: return -1.0;\n            case 10: return -0.5773502691896257;\n        }\n        return s / c;\n    }\n    return tan(x);\n}\nstatic double dan_ctg(double x, int line) {\n    int64_t k;\n    if (dan_table_angle(x, &k)) {\n        double s = dan_sin_table(k, x), c = dan_sin_table((k + 6) % 24, x + 1.5707963267948966);\n        if (s == 0) dan_error(DAN_MSG_CTG, line);\n        switch (k % 12) {\n            case 6: return 0.0;\n            case 2: return 1.7320508075688772;\n            case 3: return 1.0;\n            case 4: return 0.5773502691896257;\n            case 8: return -0.5773502691896257;\n            case 9: return -1.0;\n            case 10: return -1.7320508075688772;\n        }\n        return c / s;\n    }\n    return cos(x) / sin(x);\n}\nstatic double dan_asin(double x, int line) { if (x < -1 || x > 1) dan_error(DAN_MSG_ASIN, line); return asin(x); }\nstatic double dan_acos(double x, int line) { if (x < -1 || x > 1) dan_error(DAN_MSG_ASIN, line); return acos(x); }\nstatic double dan_acot(double x, int line) { (void)line; return 1.5707963267948966 - atan(x); }\nstatic double dan_ln(double x, int line) { if (!(x > 0)) dan_error(DAN_MSG_LOG, line); return log(x); }\nstatic double dan_lg(double x, int line) { if (!(x > 0)) dan_error(DAN_MSG_LOG, line); return log10(x); }\nstatic double dan_log(double b, double x, int line) {\n    if (!(b > 0) || b == 1) dan_error(DAN_MSG_LOG_BASE, line);\n    if (!(x > 0)) dan_error(DAN_MSG_LOG, line);\n    double r = log(x) / log(b);\n    double k = nearbyint(r);\n    if (fabs(r - k) < 1e-12 && pow(b, k) == x) return k;   /* \320\273\320\276\320\263\320\260\321\200\320\270\321\204\320\274(2, 8) = 3.0 \321\200\320\276\320\262\320\275\320\276 */\n    return r;\n}\nstatic double dan_to_radians(double g) { return g * 3.141592653589793 / 180.0; }\nstatic double dan_to_degrees(double r) { return r * 180.0 / 3.141592653589793; }\nstatic double dan_nroot(double x, int64_t n, int line) {\n    if (n < 1) dan_error(DAN_MSG_ROOT_DEG, line);\n    if (n == 1) return x;\n    if (n == 2) { if (x < 0) dan_error(DAN_MSG_ROOT, line); return sqrt(x); }\n    if (n == 3) {               /* cbrt \320\275\320\265 \320\262\321\201\320\265\320\263\320\264\320\260 \320\264\320\260\321\221\321\202 \321\202\320\276\321\207\320\275\321\213\320\271 \320\272\320\276\321\200\320\265\320\275\321\214 \320\270\320\267 \321\202\320\276\321\207\320\275\320\276\320\263\320\276 \320\272\321\203\320\261\320\260: cbrt(27) = 3.0000000000000004 */\n");
DAN_STATIC_STR(dan_lit_1903, "        double r = cbrt(x), k = nearbyint(r);\n        return fabs(r - k) < 1e-9 && k * k * k == x \? k : r;\n    }\n    if (x < 0) { if (n % 2 == 0) dan_error(DAN_MSG_ROOT, line); return -pow(-x, 1.0 / (double)n); }\n    double r = pow(x, 1.0 / (double)n), k = nearbyint(r);\n    if (fabs(r - k) < 1e-9 && pow(k, (double)n) == x) return k;\n    return r;\n}\nstatic int64_t dan_sign_int(int64_t x) { return (x > 0) - (x < 0); }\nstatic int64_t dan_sign_rat(dan_rat x) { return (x.n > 0) - (x.n < 0); }\nstatic int64_t dan_sign_float(double x) { return (x > 0) - (x < 0); }\nstatic int64_t dan_floor_rat(dan_rat x) { int64_t q = x.n / x.d; if (x.n % x.d != 0 && x.n < 0) q--; return q; }\nstatic int64_t dan_ceil_rat(dan_rat x) { int64_t q = x.n / x.d; if (x.n % x.d != 0 && x.n > 0) q++; return q; }\nstatic int64_t dan_float_to_i64(double v, int line) {\n    if (!(v >= -9223372036854775808.0 && v < 9223372036854775808.0)) dan_error(DAN_MSG_FLOAT_RANGE, line);\n    return (int64_t)v;\n}\nstatic int64_t dan_floor_float(double x, int line) { return dan_float_to_i64(floor(x), line); }\nstatic int64_t dan_ceil_float(double x, int line) { return dan_float_to_i64(ceil(x), line); }\nstatic dan_rat dan_frac_rat(dan_rat x, int line) { return dan_rat_sub(x, dan_rat_from_int(dan_floor_rat(x), line), line); }\nstatic double dan_frac_float(double x) { return x - floor(x); }\n\n/* -- calculus of polynomials -- */\nstatic dan_mn dan_poly_derivative_n(dan_mn p, int64_t n, int line) {\n    if (n < 0) dan_error(DAN_MSG_NEG_ORDER, line);\n    for (int64_t i = 0; i < n && p->deg >= 0; i++) p = dan_poly_derivative(p, line);\n    return p;\n}\nstatic dan_mn dan_poly_antiderivative(dan_mn p, int line) {\n    dan_poly *r = dan_poly_alloc(p->deg + 1);\n    for (int64_t i = 0; i <= p->deg; i++) r->c[i + 1] = dan_rat_div(p->c[i], dan_rat_from_int(i + 1, line), line);\n    return dan_poly_trim(r);\n}\nstatic dan_rat dan_poly_integral_rat(dan_mn p, dan_rat a, dan_rat b, int line) {\n    dan_mn f = dan_poly_antiderivative(p, line);\n    return dan_rat_sub(dan_poly_eval_rat(f, b, line), dan_poly_eval_rat(f, a, line), line);\n}\nstatic double dan_poly_integral_float(dan_mn p, double a, double b, int line) {\n    dan_mn f = dan_poly_antiderivative(p, line);\n    return dan_poly_eval_float(f, b) - dan_poly_eval_float(f, a);\n}\nstatic dan_mn dan_poly_tangent(dan_mn p, dan_rat a, int line) {\n    dan_rat fa = dan_poly_eval_rat(p, a, line);\n    dan_rat k = dan_poly_eval_rat(dan_poly_derivative(p, line), a, line);\n    dan_mn kx = dan_poly_scale(dan_poly_x(), k, line);\n    return dan_poly_add(kx, dan_poly_const(dan_rat_sub(fa, dan_rat_mul(k, a, line), line)), line);\n}\nstatic dl_Lf *dan_poly_critical(dan_mn p, int line) {\n    dan_mn d = dan_poly_derivative(p, line);\n    if (d->deg < 1) return dl_Lf_from(0, NULL);\n    return dan_solve_real(d, line);\n}\n\n/* -- combinatorics -- */\nstatic int64_t dan_mul_chk(int64_t a, int64_t b, int line) {\n    int64_t r;\n    if (__builtin_mul_overflow(a, b, &r)) dan_error(DAN_MSG_TOO_BIG, line);\n    return r;\n}\nstatic int64_t dan_factorial(int64_t n, int line) {\n    if (n < 0) dan_error(DAN_MSG_NEG_FACT, line);\n    int64_t r = 1;\n    for (int64_t i = 2; i <= n; i++) r = dan_mul_chk(r, i, line);\n    return r;\n}\nstatic void dan_comb_check(int64_t n, int64_t k, int line) { if (k < 0 || n < 0 || k > n) dan_error(DAN_MSG_COMB_RANGE, line); }\nstatic int64_t dan_arrangements(int64_t n, int64_t k, int line) {\n    dan_comb_check(n, k, line);\n    int64_t r = 1;\n    for (int64_t i = 0; i < k; i++) r = dan_mul_chk(r, n - i, line);\n    return r;\n}\nstatic int64_t dan_binom(int64_t n, int64_t k, int line) {\n    dan_comb_check(n, k, line);\n    if (k > n - k) k = n - k;\n    dan_u128 r = 1;\n    for (int64_t i = 1; i <= k; i++) {\n        r = r * (dan_u128)(n - k + i) / (dan_u128)i;     /* \320\264\320\265\320\273\320\270\321\202\321\201\321\217 \320\275\320\260\321\206\320\265\320\273\320\276 \320\275\320\260 \320\272\320\260\320\266\320\264\320\276\320\274 \321\210\320\260\320\263\320\265 */\n        if (r > (dan_u128)INT64_MAX) dan_error(DAN_MSG_TOO_BIG, line);\n    }\n    return (int64_t)r;\n}\nstatic int64_t dan_arr_rep(int64_t n, int64_t k, int line) {\n");
DAN_STATIC_STR(dan_lit_1904, "    if (n < 0 || k < 0) dan_error(DAN_MSG_COMB_RANGE, line);\n    return dan_pow_int(n, k, line);\n}\nstatic int64_t dan_comb_rep(int64_t n, int64_t k, int line) {\n    if (n < 1) dan_error(DAN_MSG_COMB_N, line);\n    if (k < 0) dan_error(DAN_MSG_COMB_RANGE, line);\n    int64_t t;\n    if (__builtin_add_overflow(n, k - 1, &t)) dan_error(DAN_MSG_TOO_BIG, line);\n    return dan_binom(t, k, line);\n}\nstatic int64_t dan_multinomial(const dl_Li *l, int line) {\n    int64_t total = 0, r = 1;\n    for (int64_t i = 0; i < l->len; i++) {\n        if (l->items[i] < 0) dan_error(DAN_MSG_COMB_RANGE, line);\n        if (__builtin_add_overflow(total, l->items[i], &total)) dan_error(DAN_MSG_TOO_BIG, line);\n        r = dan_mul_chk(r, dan_binom(total, l->items[i], line), line);\n    }\n    return r;\n}\n\n/* -- probability and statistics -- */\nstatic dan_rat dan_classical_prob(int64_t m, int64_t n, int line) {\n    if (n <= 0 || m < 0 || m > n) dan_error(DAN_MSG_PROB_RANGE, line);\n    return dan_rat_of(m, n, line);\n}\nstatic dan_rat dan_bernoulli_rat(int64_t n, int64_t k, dan_rat p, int line) {\n    if (p.n < 0 || p.n > p.d) dan_error(DAN_MSG_P_RANGE, line);\n    dan_rat c = dan_rat_from_int(dan_binom(n, k, line), line);\n    dan_rat q = dan_rat_sub(dan_rat_from_int(1, line), p, line);\n    return dan_rat_mul(c, dan_rat_mul(dan_rat_pow(p, k, line), dan_rat_pow(q, n - k, line), line), line);\n}\nstatic double dan_bernoulli_float(int64_t n, int64_t k, double p, int line) {\n    if (!(p >= 0 && p <= 1)) dan_error(DAN_MSG_P_RANGE, line);\n    dan_comb_check(n, k, line);\n    double lc = lgamma((double)n + 1) - lgamma((double)k + 1) - lgamma((double)(n - k) + 1);\n    if (p == 0) return k == 0 \? 1.0 : 0.0;\n    if (p == 1) return k == n \? 1.0 : 0.0;\n    return exp(lc + (double)k * log(p) + (double)(n - k) * log1p(-p));\n}\nstatic void dan_dist_check_rat(const dl_Lr *x, const dl_Lr *p, int line) {\n    if (x->len != p->len) dan_error(DAN_MSG_DIST_LEN, line);\n    if (x->len == 0) dan_error(DAN_MSG_STAT_EMPTY, line);\n    dan_rat s = { 0, 1 };\n    for (int64_t i = 0; i < p->len; i++) {\n        if (p->items[i].n < 0) dan_error(DAN_MSG_P_RANGE, line);\n        s = dan_rat_add(s, p->items[i], line);\n    }\n    if (!(s.n == 1 && s.d == 1)) dan_error(DAN_MSG_DIST_SUM, line);\n}\nstatic dan_rat dan_expect_rat(const dl_Lr *x, const dl_Lr *p, int line) {\n    dan_dist_check_rat(x, p, line);\n    dan_rat s = { 0, 1 };\n    for (int64_t i = 0; i < x->len; i++) s = dan_rat_add(s, dan_rat_mul(x->items[i], p->items[i], line), line);\n    return s;\n}\nstatic double dan_expect_float(const dl_Lf *x, const dl_Lf *p, int line) {\n    if (x->len != p->len) dan_error(DAN_MSG_DIST_LEN, line);\n    if (x->len == 0) dan_error(DAN_MSG_STAT_EMPTY, line);\n    double s = 0, ps = 0;\n    for (int64_t i = 0; i < x->len; i++) {\n        if (p->items[i] < 0) dan_error(DAN_MSG_P_RANGE, line);\n        s += x->items[i] * p->items[i]; ps += p->items[i];\n    }\n    if (fabs(ps - 1) > 1e-9) dan_error(DAN_MSG_DIST_SUM, line);\n    return s;\n}\nstatic dan_rat dan_var_dist_rat(const dl_Lr *x, const dl_Lr *p, int line) {\n    dan_rat m = dan_expect_rat(x, p, line), s = { 0, 1 };\n    for (int64_t i = 0; i < x->len; i++) {\n        dan_rat dlt = dan_rat_sub(x->items[i], m, line);\n        s = dan_rat_add(s, dan_rat_mul(p->items[i], dan_rat_mul(dlt, dlt, line), line), line);\n    }\n    return s;\n}\nstatic dl_Lr *dan_ints_to_rats(const dl_Li *l, int line) {\n    dl_Lr *r = dl_Lr_from(0, NULL);\n    for (int64_t i = 0; i < l->len; i++) dl_Lr_push(r, dan_rat_from_int(l->items[i], line));\n    return r;\n}\nstatic dl_Lf *dan_ints_to_floats(const dl_Li *l) {\n    dl_Lf *r = dl_Lf_from(0, NULL);\n    for (int64_t i = 0; i < l->len; i++) dl_Lf_push(r, (double)l->items[i]);\n    return r;\n}\nstatic dan_rat dan_var_core_rat(const dl_Lr *l, int64_t minus, int line) {\n    if (l->len < 1 + minus) dan_error(minus \? DAN_MSG_STAT_TWO : DAN_MSG_STAT_EMPTY, line);\n    dan_rat s = { 0, 1 };\n    for (int64_t i = 0; i < l->len; i++) s = dan_rat_add(s, l->items[i], line);\n");
DAN_STATIC_STR(dan_lit_1905, "    dan_rat m = dan_rat_div(s, dan_rat_from_int(l->len, line), line), q = { 0, 1 };\n    for (int64_t i = 0; i < l->len; i++) {\n        dan_rat dlt = dan_rat_sub(l->items[i], m, line);\n        q = dan_rat_add(q, dan_rat_mul(dlt, dlt, line), line);\n    }\n    return dan_rat_div(q, dan_rat_from_int(l->len - minus, line), line);\n}\nstatic double dan_var_core_float(const dl_Lf *l, int64_t minus, int line) {\n    if (l->len < 1 + minus) dan_error(minus \? DAN_MSG_STAT_TWO : DAN_MSG_STAT_EMPTY, line);\n    double m = 0;\n    for (int64_t i = 0; i < l->len; i++) m += l->items[i];\n    m /= (double)l->len;\n    double q = 0;\n    for (int64_t i = 0; i < l->len; i++) q += (l->items[i] - m) * (l->items[i] - m);\n    return q / (double)(l->len - minus);\n}\nstatic dan_rat dan_var_rat(const dl_Lr *l, int line) { return dan_var_core_rat(l, 0, line); }\nstatic dan_rat dan_svar_rat(const dl_Lr *l, int line) { return dan_var_core_rat(l, 1, line); }\nstatic dan_rat dan_var_rat_i(const dl_Li *l, int line) { return dan_var_core_rat(dan_ints_to_rats(l, line), 0, line); }\nstatic dan_rat dan_svar_rat_i(const dl_Li *l, int line) { return dan_var_core_rat(dan_ints_to_rats(l, line), 1, line); }\nstatic double dan_var_float(const dl_Lf *l, int line) { return dan_var_core_float(l, 0, line); }\nstatic double dan_svar_float(const dl_Lf *l, int line) { return dan_var_core_float(l, 1, line); }\nstatic double dan_sd_float(const dl_Lf *l, int line) { return sqrt(dan_var_core_float(l, 0, line)); }\nstatic double dan_sd_rat(const dl_Lr *l, int line) { return sqrt(dan_rat_to_float(dan_var_core_rat(l, 0, line))); }\nstatic double dan_sd_i(const dl_Li *l, int line) { return dan_sd_float(dan_ints_to_floats(l), line); }\nstatic void dan_series_check(const dl_Lf *x, const dl_Lf *y, int line) {\n    if (x->len != y->len) dan_error(DAN_MSG_SERIES_LEN, line);\n    if (x->len < 2) dan_error(DAN_MSG_STAT_TWO, line);\n}\nstatic void dan_moments(const dl_Lf *x, const dl_Lf *y, double *sxx, double *syy, double *sxy, double *mx, double *my) {\n    double n = (double)x->len, ax = 0, ay = 0;\n    for (int64_t i = 0; i < x->len; i++) { ax += x->items[i]; ay += y->items[i]; }\n    ax /= n; ay /= n;\n    double a = 0, b = 0, c = 0;\n    for (int64_t i = 0; i < x->len; i++) {\n        double dx = x->items[i] - ax, dy = y->items[i] - ay;\n        a += dx * dx; b += dy * dy; c += dx * dy;\n    }\n    *sxx = a; *syy = b; *sxy = c; *mx = ax; *my = ay;\n}\nstatic double dan_corr_float(const dl_Lf *x, const dl_Lf *y, int line) {\n    dan_series_check(x, y, line);\n    double a, b, c, mx, my;\n    dan_moments(x, y, &a, &b, &c, &mx, &my);\n    if (a == 0 || b == 0) dan_error(DAN_MSG_CONST_SERIES, line);\n    return c / sqrt(a * b);\n}\nstatic double dan_corr_i(const dl_Li *x, const dl_Li *y, int line) { return dan_corr_float(dan_ints_to_floats(x), dan_ints_to_floats(y), line); }\nstatic dl_Lf *dan_linreg_float(const dl_Lf *x, const dl_Lf *y, int line) {\n    dan_series_check(x, y, line);\n    double a, b, c, mx, my;\n    dan_moments(x, y, &a, &b, &c, &mx, &my);\n    if (a == 0) dan_error(DAN_MSG_CONST_SERIES, line);\n    double k = c / a;\n    double kb[2] = { k, my - k * mx };\n    return dl_Lf_from(2, kb);\n}\nstatic dl_Lf *dan_linreg_i(const dl_Li *x, const dl_Li *y, int line) { return dan_linreg_float(dan_ints_to_floats(x), dan_ints_to_floats(y), line); }\nstatic double dan_entropy(const dl_Lf *p, int line) {\n    if (p->len == 0) dan_error(DAN_MSG_STAT_EMPTY, line);\n    double s = 0, h = 0;\n    for (int64_t i = 0; i < p->len; i++) {\n        if (p->items[i] < 0) dan_error(DAN_MSG_P_RANGE, line);\n        s += p->items[i];\n        if (p->items[i] > 0) h -= p->items[i] * log2(p->items[i]);\n    }\n    if (fabs(s - 1) > 1e-9) dan_error(DAN_MSG_DIST_SUM, line);\n    return h + 0.0;\n}\n\n/* random numbers: xoshiro256** seeded from the clock once per run */\nstatic DAN_TLS uint64_t dan_rng_s[4];\nstatic DAN_TLS bool dan_rng_ready = false;\nstatic uint64_t dan_rng_mix(uint64_t *x) {\n    uint64_t z = (*x += 0x9E3779B97F4A7C15ULL);\n");
